&lt;td&gt;&amp;lt; 100&lt;/td&gt;
&lt;td&gt;&amp;gt; 500&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Hard bounce rate&lt;/td&gt;
&lt;td&gt;&amp;lt; 0.1%&lt;/td&gt;
&lt;td&gt;&amp;gt; 0.5%&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5xx error rate&lt;/td&gt;
