&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;

&lt;h3&gt;


  Bulk Campaign Metrics Dashboard
&lt;/h3&gt;

&lt;div class="table-wrapper-paragraph"&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Metric&lt;/th&gt;
&lt;th&gt;Target&lt;/th&gt;
&lt;th&gt;Alert&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Campaign delivery rate&lt;/td&gt;
&lt;td&gt;&amp;gt; 96%&lt;/td&gt;
&lt;td&gt;&amp;lt; 93%&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Campaign completion time&lt;/td&gt;
&lt;td&gt;&amp;lt; 4 hours&lt;/td&gt;
&lt;td&gt;&amp;gt; 8 hours&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
